"""IngeTrazo Bevel V1.0 — independent polygon-mesh bevel implementation.

Distances in the dialog are millimetres; engine coordinates are metres.
No reference-extension source or assets are included.
"""
from __future__ import annotations
import copy
import base64
import math
import numpy as np
from PySide6.QtCore import Qt, QSize, QPointF
from PySide6.QtGui import QColor, QPainter, QPen, QPixmap, QIcon, QVector3D, QPolygonF
from PySide6.QtWidgets import (QDialog,QVBoxLayout,QHBoxLayout,QFormLayout,QLabel,
    QDoubleSpinBox,QSpinBox,QComboBox,QPushButton,QMessageBox,QToolBar,QWidget)
from core.mesh import Mesh,Edge,Face,edge_flags,stamp_edge_flags
from core.history import Command

KEY='ingetrazo_bevel'
VERSION='1.0.2'
TITLE='IngeTrazo Bevel V1.0'


def unit(v):
    length=float(np.linalg.norm(v))
    if length<1e-10: raise ValueError('Degenerate edge or corner. Clean the source mesh first.')
    return v/length


def point_key(p):
    return tuple(round(float(x)*10000) for x in p)


def edge_key(a,b):
    return tuple(sorted((point_key(a),point_key(b))))


def normal(points):
    return unit(sum((np.cross(a,b) for a,b in zip(points,points[1:]+points[:1])),np.zeros(3)))


def rounded_corner(loop,segments,width):
    """Tessellate a co-spherical boundary onto its sphere, keeping its rim exact.

    Three orthogonal rounded edges meet on a spherical octant. A centroid fan
    closes the hole but cuts that octant flat. Fit in a local frame for numerical
    stability; only use this construction when the entire rim fits one sphere.
    Other junction types retain the conservative polygon patch.
    """
    if segments<2 or len(loop)<6:return None
    origin=sum(loop)/len(loop)
    local=np.array(loop)-origin
    matrix=np.column_stack((2*local,np.ones(len(loop))))
    solution,_,rank,_=np.linalg.lstsq(matrix,np.sum(local*local,axis=1),rcond=None)
    if rank<4:return None
    center=origin+solution[:3]
    radii=np.linalg.norm(np.array(loop)-center,axis=1)
    radius=float(np.mean(radii))
    if not .1*width<radius<4*width or np.max(np.abs(radii-radius))>max(1e-9,radius*1e-5):return None
    direction=unit(origin-center)
    # Avoid spanning a major sphere region or crossing its centre.
    if any(np.dot(unit(p-center),direction)<.15 for p in loop):return None
    tip=center+radius*direction
    rings=max(1,(segments+1)//2)
    triangles=[];outer=loop
    for step in range(1,rings):
        t=step/rings
        inner=[center+radius*unit((1-t)*(p-center)+t*(tip-center)) for p in loop]
        for i in range(len(loop)):
            j=(i+1)%len(loop)
            triangles.extend(([outer[i],outer[j],inner[j]],[outer[i],inner[j],inner[i]]))
        outer=inner
    triangles.extend([a,b,tip] for a,b in zip(outer,outer[1:]+outer[:1]))
    return triangles


def bevel_mesh(source, chosen=None, width=.01, segments=1, angle=30., soften=True):
    """Inset adjacent face boundaries, bridge edge profiles, close vertex gaps.

    Closed orientable polygon surfaces only. Explicit selections may include
    concave edges. Coplanar edges remain unchanged. Ambiguous mitres fail before
    touching the document. Rounding uses rational quadratic tangent profiles.
    """
    if not math.isfinite(width) or width<.001: raise ValueError('Use an offset of at least 1 mm.')
    if not 1<=segments<=12 or int(segments)!=segments: raise ValueError('Use 1–12 segments.')
    if not math.isfinite(angle) or not 0<=angle<=179: raise ValueError('Angle must be 0–179 degrees.')
    if not source.faces or len(source.faces)>6000: raise ValueError('Select a mesh with 1–6000 faces.')
    if any(len(e.faces)!=2 for e in source.edges):
        raise ValueError('The mesh must be a closed solid: remove loose edges and repair open or non-manifold boundaries.')
    if any(f.hole_loops for f in source.faces):
        raise ValueError('Faces with hole loops need subdivision into simple polygons first.')
    points={v:np.array(v.position.toTuple(),dtype=float) for v in source.vertices}
    normals={f:normal([points[v] for v in f.loop]) for f in source.faces}
    for f in source.faces:
        if len(f.loop)>256: raise ValueError('Subdivide faces with more than 256 corners before beveling.')
        origin=points[f.loop[0]]
        if any(abs(np.dot(points[v]-origin,normals[f]))>.00005 for v in f.loop):
            raise ValueError('A source face is nonplanar. Triangulate or repair it before beveling.')
    pending=set(source.faces)
    while pending:
        first=next(iter(pending));stack=[first];component=[];pending.remove(first)
        while stack:
            f=stack.pop();component.append(f)
            for v in f.loop:
                for e in v.edges:
                    for neighbor in e.faces:
                        if neighbor in pending:pending.remove(neighbor);stack.append(neighbor)
        origin=points[component[0].loop[0]]
        volume=0.
        for f in component:
            p=[points[v]-origin for v in f.loop]
            for i in range(1,len(p)-1):volume+=np.dot(p[0],np.cross(p[i],p[i+1]))/6
        if volume<=1e-12:raise ValueError('A shell has inward-facing normals or no volume. Orient faces outward first.')
    lookup={frozenset((e.v0,e.v1)):e for e in source.edges}
    selected=set()
    if chosen is not None and any(e not in source.edges for e in chosen):
        raise ValueError('The edge selection is stale. Reopen the tool.')
    for e in source.edges:
        f,g=e.faces
        turn=math.degrees(math.acos(float(np.clip(np.dot(normals[f],normals[g]),-1,1))))
        if turn<.01: continue
        if (chosen is None and turn>=angle) or (chosen is not None and e in chosen): selected.add(e)
        # Adjacent face loops must traverse the common edge in opposite directions.
        def direction(face):
            return any(a is e.v0 and b is e.v1 for a,b in zip(face.loop,face.loop[1:]+face.loop[:1]))
        if direction(f)==direction(g): raise ValueError('Inconsistent face orientation. Orient the solid faces consistently first.')
    if not selected: raise ValueError('No eligible edges. Select non-coplanar edges or lower the angle threshold.')
    if len(source.faces)+2*segments*len(selected)+sum(len(f.loop) for f in source.faces)>40000:
        raise ValueError('This selection would generate too many faces. Work on a smaller solid or use fewer segments.')
    if any(e.length()<width*2.1 for e in selected):
        raise ValueError('The offset is too large for a selected edge. Reduce it.')
    corners={}; corner_edges={}; trimmed={}
    # Intersect the two parallel-offset lines in each incident face plane.
    for f in source.faces:
        for i,v in enumerate(f.loop):
            prev,nxt=f.loop[i-1],f.loop[(i+1)%len(f.loop)]
            ein,eout=lookup[frozenset((prev,v))],lookup[frozenset((v,nxt))]
            incoming=unit(points[v]-points[prev]);outgoing=unit(points[nxt]-points[v])
            ni,no=np.cross(normals[f],incoming),np.cross(normals[f],outgoing)
            offsets=np.array([width if ein in selected else 0.,width if eout in selected else 0.,0.])
            mat=np.array([ni,no,normals[f]])
            if np.linalg.cond(mat)>1e8:
                if np.any(offsets): raise ValueError('A straight or nearly parallel face corner needs cleaning before beveling.')
                delta=np.zeros(3)
            else: delta=np.linalg.solve(mat,offsets)
            if np.linalg.norm(delta)>min(np.linalg.norm(points[v]-points[prev]),np.linalg.norm(points[nxt]-points[v]))*.45:
                raise ValueError('The offset collides near a corner. Reduce it or simplify this junction.')
            corners[f,v]=points[v]+delta
            corner_edges[f,v]=(ein,eout)
            if (ein in selected)!=(eout in selected):
                plain=eout if ein in selected else ein
                existing=trimmed.get((plain,v))
                if existing is not None and np.linalg.norm(existing-corners[f,v])>.00005:
                    raise ValueError('Unequal mitres meet at an unselected edge. Select the adjoining edge too, or bevel this junction separately.')
                trimmed[plain,v]=corners[f,v]
    patches=[]
    def emit(pts,attrs,role):
        compact=[]
        for p in pts:
            if not compact or point_key(compact[-1])!=point_key(p): compact.append(p)
        if len(compact)>1 and point_key(compact[0])==point_key(compact[-1]): compact.pop()
        if len({point_key(p) for p in compact})<3:
            raise ValueError('A bevel face collapsed below the host mesh precision. Increase offset or reduce segments.')
        patches.append((compact,copy.deepcopy(attrs),role))
    for f in source.faces:
        facepoints=[]
        for v in f.loop:
            ein,eout=corner_edges[f,v]
            if ein in selected or eout in selected:
                facepoints.append(corners[f,v])
            else:
                a=trimmed.get((ein,v),points[v]);b=trimmed.get((eout,v),points[v])
                # A single selected edge clips the corner of its third face.
                if (ein,v) in trimmed or (eout,v) in trimmed:
                    if (ein,v) in trimmed: facepoints.append(a)
                    if (eout,v) in trimmed: facepoints.append(b)
                else: facepoints.append(points[v])
        if np.dot(normal(facepoints),normals[f])<.9:
            raise ValueError('A face collapsed or reversed. Reduce the offset.')
        # Detect crossing edges in the trimmed face before attempting a mesh.
        axis=unit(points[f.loop[1]]-points[f.loop[0]]);second=np.cross(normals[f],axis)
        flat=[(float(np.dot(p,axis)),float(np.dot(p,second))) for p in facepoints]
        def side(a,b,c):return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
        n=len(flat)
        for i in range(n):
            a,b=flat[i],flat[(i+1)%n]
            for j in range(i+2,n):
                if i==0 and j==n-1:continue
                c,d=flat[j],flat[(j+1)%n]
                if side(a,b,c)*side(a,b,d)<-1e-16 and side(c,d,a)*side(c,d,b)<-1e-16:
                    raise ValueError('Offset edges cross inside a face. Reduce the width.')
        emit(facepoints,f.attrs,'original')
    for e in selected:
        f,g=e.faces
        # Order the edge as it appears on the first face.
        a,b=e.v0,e.v1
        if not any(x is a and y is b for x,y in zip(f.loop,f.loop[1:]+f.loop[:1])): a,b=b,a
        tangent=unit(points[b]-points[a])
        profiles=[]
        for v in (a,b):
            A,B=corners[f,v],corners[g,v]
            control=points[v]+tangent*np.dot((A+B)/2-points[v],tangent)
            if segments==1: profile=[A,B]
            else:
                av,bv=A-control,B-control
                cosine=float(np.clip(np.dot(unit(av),unit(bv)),-1,1))
                weight=math.sqrt(max(.001,(1-cosine)/2))
                profile=[]
                for s in range(segments+1):
                    t=s/segments
                    profile.append(((1-t)**2*A+2*weight*t*(1-t)*control+t*t*B)/((1-t)**2+2*weight*t*(1-t)+t*t))
            profiles.append(profile)
        for i in range(segments):
            # Reverse the first face's edge so shared boundary winding agrees.
            quad=[profiles[0][i],profiles[0][i+1],profiles[1][i+1],profiles[1][i]]
            # Triangle pairs support skewed corner profiles without nonplanar faces.
            emit(quad[:3],f.attrs,'bevel');emit([quad[0],quad[2],quad[3]],f.attrs,'bevel')
    # Surface borders now consist only of the missing vertex caps. Follow their
    # directed loops and add oppositely oriented triangle fans.
    incidence={}
    for pts,attrs,role in patches:
        for a,b in zip(pts,pts[1:]+pts[:1]): incidence.setdefault(edge_key(a,b),[]).append((a,b,attrs))
    if any(len(v)>2 for v in incidence.values()): raise ValueError('Bevel faces overlap at a junction. Reduce the offset or change the selection.')
    boundary={}
    for uses in incidence.values():
        if len(uses)==1:
            a,b,attrs=uses[0]
            if point_key(a) in boundary: raise ValueError('Ambiguous corner boundary. Simplify the edge junction.')
            boundary[point_key(a)]=(a,b,attrs)
    while boundary:
        first=next(iter(boundary));key=first;loop=[];attrs={}
        while True:
            if key not in boundary: raise ValueError('A corner could not be closed safely.')
            a,b,attrs=boundary.pop(key);loop.append(a);key=point_key(b)
            if key==first: break
            if len(loop)>200: raise ValueError('Corner boundary too complex.')
        if len(loop)<3: raise ValueError('Collapsed corner. Increase offset or reduce segments.')
        loop.reverse()
        curved=rounded_corner(loop,segments,width)
        if curved is not None:
            for triangle in curved:emit(triangle,attrs,'bevel')
        elif len(loop)==3: emit(loop,attrs,'bevel')
        else:
            center=sum(loop)/len(loop)
            for a,b in zip(loop,loop[1:]+loop[:1]): emit([a,b,center],attrs,'bevel')
    if len(patches)>40000:raise ValueError('Rounded corners exceed the face budget. Reduce segments or select fewer edges.')
    result=Mesh();roles={}
    for pts,attrs,role in patches:
        face=result.add_face([QVector3D(*map(float,p)) for p in pts]);face.attrs=attrs;roles[face]=role
    if any(len(e.faces)!=2 for e in result.edges):
        raise ValueError('Result failed the closed-solid check. Increase offset or reduce segments.')
    retained={edge_key(trimmed.get((e,e.v0),points[e.v0]),trimmed.get((e,e.v1),points[e.v1])):edge_flags(e)
              for e in source.edges if e not in selected}
    for e in result.edges:
        if e.v0 is e.v1: raise ValueError('Result contains collapsed edges.')
        flags=retained.get(edge_key(e.a.toTuple(),e.b.toTuple()))
        if flags is not None: stamp_edge_flags(e,flags)
        if soften:
            f,g=e.faces
            dot=QVector3D.dotProduct(f.normal(),g.normal())
            if dot>.9999 or (roles[f]==roles[g]=='bevel' and segments>1 and dot>math.cos(math.radians(65))): e.soft=True
    if any(f.normal().length()<.5 for f in result.faces):raise ValueError('A result face has zero area. Reduce segments or adjust the offset.')
    return result,len(selected)


class ReplaceMesh(Command):
    def __init__(self,target,result,group=None):
        self.target=target;self.result=result;self.group=group
        self.before=target.capture_state();self.after=result.capture_state()
    def do(self,scene):
        if self.group:
            if self.group not in scene.groups: raise ValueError('The selected group is no longer present.')
            self.group.mesh=self.result
        else: self.target.restore_state(self.after)
        scene.selection.clear();scene.version+=1
    def undo(self,scene):
        if self.group: self.group.mesh=self.target
        else: self.target.restore_state(self.before)
        scene.selection.clear();scene.version+=1


def target_from(app):
    scene=app.scene
    groups=[g for g in scene.groups if g in scene.selection]
    if groups:
        if len(groups)!=1 or len(scene.selection)!=1: raise ValueError('Select one mesh group, or select edges inside a group.')
        g=groups[0]
        if g.children: raise ValueError('Open the assembly and select the edges of one solid part. Nested assemblies are not flattened automatically.')
        if g.xform is not None:
            # Offset is local-space; nonuniform scale is too misleading for a mm UI.
            vectors=[g.xform.mapVector(QVector3D(*v)).length() for v in ((1,0,0),(0,1,0),(0,0,1))]
            if any(abs(x-1)>1e-4 for x in vectors): raise ValueError('Apply/bake the group scale before beveling so millimetre offsets remain accurate.')
        return g.mesh,None,g
    chosen={e for e in scene.selection if isinstance(e,Edge) and e in scene.mesh.edges}
    for f in scene.selection:
        if isinstance(f,Face) and f in scene.mesh.faces:
            chosen.update(e for e in scene.mesh.edges if f in e.faces)
    if not chosen: raise ValueError('Select solid edges/faces, or select one solid mesh group.')
    return scene.mesh,chosen,None


class Preview(QWidget):
    """Read-only local-space wireframe; the actual document is never preview-mutated."""
    def __init__(self,mesh):
        super().__init__();self.mesh=mesh;self.setMinimumSize(400,340)
    def paintEvent(self,event):
        painter=QPainter(self);painter.setRenderHint(QPainter.Antialiasing)
        painter.fillRect(self.rect(),QColor('#102338'))
        if not self.mesh or not self.mesh.vertices:return
        points={v:(v.position.x()+.55*v.position.y(),.22*v.position.x()-.35*v.position.y()-v.position.z()) for v in self.mesh.vertices}
        low=[min(p[k] for p in points.values()) for k in (0,1)];high=[max(p[k] for p in points.values()) for k in (0,1)]
        scale=min((self.width()-40)/max(high[0]-low[0],1e-8),(self.height()-60)/max(high[1]-low[1],1e-8))
        def screen(v):
            x,y=points[v]
            return QPointF(self.width()/2+(x-(low[0]+high[0])/2)*scale,self.height()/2-10+(y-(low[1]+high[1])/2)*scale)
        painter.setPen(QPen(QColor('#4694b8'),.6))
        for e in self.mesh.edges:painter.drawLine(screen(e.v0),screen(e.v1))
        painter.setPen(QPen(QColor('#ffbe69'),1.1))
        for e in self.mesh.edges:
            if not e.soft:painter.drawLine(screen(e.v0),screen(e.v1))
        painter.setPen(QColor('#b1c5d4'))
        painter.drawText(self.rect().adjusted(12,0,-12,-10),Qt.AlignBottom|Qt.AlignRight,'Wireframe preview · IngeTrazo Tutorials')


class Editor(QDialog):
    def __init__(self,app):
        super().__init__(app.window)
        self.app=app;self.scene=app.scene
        self.source,self.chosen,self.group=target_from(app)
        self.initial=self.source.capture_state()
        self.result=None
        self.setWindowTitle(TITLE);self.setWindowIcon(bevel_icon());self.resize(830,490)
        layout=QVBoxLayout(self);layout.addWidget(QLabel('<h2>IngeTrazo Bevel</h2>Chamfer and round solid mesh edges'))
        body=QHBoxLayout();layout.addLayout(body,1)
        controls=QVBoxLayout();body.addLayout(controls)
        self.canvas=Preview(self.source);body.addWidget(self.canvas,1)
        form=QFormLayout();controls.addLayout(form)
        self.width=QDoubleSpinBox();self.width.setRange(1,10000);self.width.setValue(10);self.width.setSuffix(' mm')
        self.style=QComboBox();self.style.addItems(['Chamfer','Rounded'])
        self.segments=QSpinBox();self.segments.setRange(2,12);self.segments.setValue(4)
        self.angle=QDoubleSpinBox();self.angle.setRange(0,179);self.angle.setValue(30);self.angle.setSuffix('°')
        self.angle.setEnabled(self.chosen is None)
        form.addRow('Offset along faces',self.width);form.addRow('Style',self.style)
        form.addRow('Round segments',self.segments);form.addRow('Minimum edge angle',self.angle)
        self.info=QLabel('Preview checks geometry before changing your model.\nWidth is a face offset, not a universal fillet radius.')
        self.info.setWordWrap(True);self.info.setMaximumWidth(310);controls.addWidget(self.info);controls.addStretch()
        row=QHBoxLayout();layout.addLayout(row)
        preview=QPushButton('Check preview');preview.clicked.connect(self.preview);row.addWidget(preview)
        self.apply_button=QPushButton('Apply');self.apply_button.clicked.connect(self.apply);self.apply_button.setEnabled(False);row.addWidget(self.apply_button)
        close=QPushButton('Close');close.clicked.connect(self.reject);row.addWidget(close)
        layout.addWidget(QLabel('IngeTrazo Tutorials · GPL-3.0-or-later'))
        for w in (self.width,self.segments,self.angle): w.valueChanged.connect(self.invalidate)
        self.style.currentIndexChanged.connect(self.invalidate)
        self.invalidate()
    def invalidate(self,*args):
        self.result=None;self.apply_button.setEnabled(False)
        self.segments.setEnabled(self.style.currentIndex()==1)
        self.canvas.mesh=self.source;self.canvas.update()
    def current(self):
        if self.app.scene is not self.scene or (self.group is None and self.app.scene.mesh is not self.source):
            raise ValueError('The editing context changed. Reopen Bevel.')
        if self.group and (self.group not in self.scene.groups or self.group.mesh is not self.source):
            raise ValueError('The selected object changed. Reopen Bevel.')
        snap=self.source.capture_state()
        if snap['faces']!=self.initial['faces'] or snap['edges']!=self.initial['edges'] or snap['fattrs']!=self.initial['fattrs'] or any(snap['vpos'].get(v)!=p for v,p in self.initial['vpos'].items()):
            raise ValueError('Source geometry changed. Reopen Bevel.')
        if self.group and self.group.xform is not None:
            if any(abs(self.group.xform.mapVector(QVector3D(*v)).length()-1)>1e-4 for v in ((1,0,0),(0,1,0),(0,0,1))):
                raise ValueError('The group scale changed. Apply its scale and reopen Bevel.')
    def preview(self):
        try:
            self.current()
            self.result,n=bevel_mesh(self.source,self.chosen,self.width.value()/1000,
                self.segments.value() if self.style.currentIndex() else 1,self.angle.value())
            self.info.setText(f'Validated {n} edges → {len(self.result.faces)} faces.\nApply creates one undo step. Ctrl+Z restores the original.')
            self.canvas.mesh=self.result;self.canvas.update()
            self.apply_button.setEnabled(True)
        except ValueError as e:
            self.invalidate();self.info.setText(str(e))
    def apply(self):
        try:
            self.current()
            if self.result is None: raise ValueError('Check preview first.')
            vp=self.app.viewport;vp.history.execute(ReplaceMesh(self.source,self.result,self.group))
            if vp.history.last_error: raise ValueError(vp.history.last_error)
            vp.notify_scene_changed();vp.update();self.accept()
        except ValueError as e: QMessageBox.warning(self,TITLE,str(e))


def bevel_icon():
    """User-provided logo embedded for reliable single-file installation."""
    pixmap=QPixmap()
    if not pixmap.loadFromData(base64.b64decode(_LOGO_PNG), 'PNG'):
        raise ValueError('The embedded Bevel icon could not be loaded.')
    return QIcon(pixmap)


def setup(app):
    dialogs=[]
    def launch():
        try:
            dialog=Editor(app);dialogs.append(dialog)
            dialog.finished.connect(lambda _:dialogs.remove(dialog) if dialog in dialogs else None)
            dialog.setAttribute(Qt.WA_DeleteOnClose);dialog.show()
        except ValueError as e: QMessageBox.warning(app.window,TITLE,str(e))
    toolbar=QToolBar(TITLE,app.window);toolbar.setObjectName('IngeTrazoBevelToolbarV1')
    toolbar.setMovable(True);toolbar.setFloatable(True);toolbar.setAllowedAreas(Qt.AllToolBarAreas);toolbar.setIconSize(QSize(26,26))
    action=toolbar.addAction(bevel_icon(),'Bevel selected edges / solid');action.triggered.connect(launch)
    app.window.addToolBar(toolbar)
    menu=app.add_menu(TITLE);menu.addAction(action);menu.addAction(toolbar.toggleViewAction())
    app.window._ingetrazo_bevel=(toolbar,dialogs)

_LOGO_PNG = ''
